<script setup>
import { onMounted, ref, watch } from 'vue'
import { Search, SlidersHorizontal, ExternalLink, PackageSearch } from '@lucide/vue'
import AppShell from '../components/AppShell.vue'
import { api } from '../services/api'
const items=ref([]), total=ref(0), loading=ref(true), more=ref(false), error=ref(''), query=ref(''), category=ref(''), maxPrice=ref(''), sort=ref('')
const PAGE=60
const categories=['cpu','gpu','motherboard','ram','ssd','hdd','psu','case','cooler','laptop','laptop_ram','external_storage','bundle','accessory']
let timer, latest=0
function params(offset){const p=new URLSearchParams({limit:String(PAGE),offset:String(offset),in_stock:'true'});if(query.value.trim())p.set('q',query.value.trim());if(category.value)p.set('category',category.value);if(Number(maxPrice.value)>0)p.set('max_price',String(maxPrice.value));if(sort.value)p.set('sort',sort.value);return p.toString()}
// Only the newest search may fill the page; a failed request says so instead of showing "no matches".
async function load(){const ticket=++latest;loading.value=true;error.value='';try{const data=await api.prices(params(0));if(ticket!==latest)return;items.value=data.items;total.value=data.total}catch{if(ticket===latest){items.value=[];total.value=0;error.value='The catalogue could not be loaded. Check that the backend is running, then search again.'}}finally{if(ticket===latest)loading.value=false}}
async function loadMore(){more.value=true;try{const data=await api.prices(params(items.value.length));items.value=[...items.value,...data.items]}catch{error.value='More offers could not be loaded.'}finally{more.value=false}}
watch([query,category,maxPrice,sort],()=>{clearTimeout(timer);timer=setTimeout(load,250)});onMounted(load)
const money=v=>new Intl.NumberFormat('en-SG',{style:'currency',currency:'SGD',maximumFractionDigits:0}).format(v)
const collected=v=>v?new Date(v).toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric'}):''
const sourceUrl=v=>/^https?:\/\//i.test(v||'')?v:`https://${v}`
</script>
<template><AppShell><div class="content-page"><div class="page-heading"><div><span class="eyebrow">SINGAPORE CATALOGUE</span><h1>Explore components</h1><p>Browse collected offers with source and collection context.</p></div><span class="count-badge">{{total.toLocaleString()}} matches</span></div><div class="catalog-toolbar"><label class="search-field"><Search :size="18"/><input v-model="query" placeholder="Search product name…"/></label><label><SlidersHorizontal :size="17"/><select v-model="category"><option value="">All categories</option><option v-for="cat in categories" :key="cat" :value="cat">{{cat.replaceAll('_',' ')}}</option></select></label><label><select v-model="sort" aria-label="Sort"><option value="">Best match</option><option value="price_asc">Price: low to high</option><option value="price_desc">Price: high to low</option></select></label><label class="price-filter">S$<input v-model="maxPrice" type="number" min="1" placeholder="Max price"/></label></div><div v-if="loading" class="catalog-grid"><div v-for="n in 8" :key="n" class="component-card skeleton"></div></div><div v-else-if="items.length" class="catalog-grid"><article v-for="item in items" :key="item.id" class="component-card"><div class="component-top"><span class="category-chip">{{item.category.replaceAll('_',' ')}}</span><span class="stock-dot">In stock</span></div><div class="component-visual"><span>{{item.brand?.slice(0,2)||item.category.slice(0,2)}}</span></div><h2>{{item.name}}</h2><p>{{item.store}}<template v-if="item.collected_at"> · price collected {{collected(item.collected_at)}}</template></p><div class="component-bottom"><strong>{{money(item.price)}}</strong><a :href="sourceUrl(item.source_url)" target="_blank" rel="noreferrer" aria-label="Open source"><ExternalLink :size="17"/></a></div></article></div><div v-else-if="error" class="empty-state"><PackageSearch :size="46"/><h2>Catalogue unavailable</h2><p>{{error}}</p></div><div v-else class="empty-state"><PackageSearch :size="46"/><h2>No matching offers</h2><p>Try another keyword, category or price ceiling.</p></div><div v-if="!loading && items.length && items.length < total" class="load-more"><button class="secondary-button" :disabled="more" @click="loadMore">{{ more ? 'Loading…' : `Show more (${items.length} of ${total.toLocaleString()})` }}</button></div><p v-if="error && items.length" class="form-error">{{error}}</p></div></AppShell></template>
